 useEffect(() => {
  let alive = true;
  let timedOut = false;
  const timeout = window.setTimeout(() => {
   timedOut = true;
   if (alive) setError('The account service did not respond. Please try again.');
  }, 8_000);

  async function loadAccount() {
   try {
    const response = await fetch('/api/auth/me', { cache: 'no-store' });
    if (!alive || timedOut) return;
    if (response.status === 401) {
     location.replace('/onboarding?mode=login&next=%2Fdashboard');
     return;
    }
    const result = await readApiJson(response, 'Could not load your account.') as { user?: U; error?: string };
    if (!alive || timedOut) return;
    if (!response.ok || !result.user || typeof result.user.id !== 'string') {
     throw new Error(result.error || 'Could not load your account. Please try again.');
    }
    window.clearTimeout(timeout);
    setUser(result.user);
    connectSocket();
    await refresh(false);
    if (!alive) return;
    setDashboardReady(true);
    setStatus(result.user.role === 'FEMALE' && result.user.profile?.online ? 'Online and ready for call requests' : 'Ready when you are');
    setSearching(false);
   } catch (reason) {
    if (alive && !timedOut) setError(reason instanceof Error ? reason.message : 'Could not connect to your account. Please try again.');
   } finally {
    window.clearTimeout(timeout);
   }
  }
  void loadAccount();
  return () => {
   alive = false;
   window.clearTimeout(timeout);
   socketRef.current?.disconnect();
   socketRef.current = null;
   streamRef.current?.getTracks().forEach(track => track.stop());
   streamRef.current = null;
   cleanPeer();
  };
 }, []);

